def split(rows, max_rate):
    good, quarantine = [], []
    for row_id, text in rows:
        try:
            value = float(text)
        except ValueError:
            quarantine.append((row_id, "not a number"))
            continue
        if value < 0:
            quarantine.append((row_id, "negative"))
        else:
            good.append((row_id, round(value * 100)))
    status = "FAIL" if len(quarantine) / len(rows) > max_rate else "OK"
    return good, quarantine, status

