independent.solution:
class TransientError(Exception):
    pass

class PermanentError(Exception):
    pass

def with_retries(fn, max_attempts, sleep):
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except TransientError:
            if attempt == max_attempts:
                raise
            sleep(2 ** (attempt - 1))

def make(failures, error):
    state = {"calls": 0}
    def fn():
        state["calls"] += 1
        if state["calls"] <= failures:
            raise error("x")
        return "ok"
    return fn, state

def run_case(fn, state):
    waits = []
    try:
        with_retries(fn, 4, waits.append)
        outcome = "ok"
    except TransientError:
        outcome = "gave up"
    except PermanentError:
        outcome = "permanent"
    return f"{outcome} after {state['calls']} calls, waits {waits}"

for failures, error in [(2, TransientError), (9, TransientError), (1, PermanentError)]:
    fn, state = make(failures, error)
    print(run_case(fn, state))
